CREATE TABLE IF NOT EXISTS club_sensitive_consent (
 id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
 user_id BIGINT NOT NULL,
 scene VARCHAR(32) NOT NULL,
 notice_version VARCHAR(64) NOT NULL,
 agreed_at DATETIME NOT NULL,
 KEY idx_consent_user (user_id, agreed_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

START TRANSACTION;
UPDATE club_content SET body_text=CONVERT( USING utf8mb4),updated_at=NOW() WHERE id=7 AND content_type='document' AND scene='agreement';
UPDATE club_content SET body_text=CONVERT( USING utf8mb4),updated_at=NOW() WHERE id=8 AND content_type='document' AND scene='privacy';
COMMIT;
